    let m = s.count / 2
    return s.count % 2 == 1 ? s[m] : (s[m - 1] + s[m]) / 2
}

private func equalOrRange(_ xs: [Int], unit: String) -> String {
    guard let lo = xs.min(), let hi = xs.max() else { return "none" }
    return lo == hi ? "equal, \(lo) \(unit) each" : "unequal, \(lo)..\(hi)"
}

